<template><div><PageHeader title="岗位管理" description="维护岗位名称和唯一编码"><el-button type="primary" :icon="Plus" @click="open()">新增岗位</el-button></PageHeader><section class="panel"><el-table v-loading="loading" :data="rows"><el-table-column prop="name" label="岗位名称" /><el-table-column prop="code" label="岗位编码" /><el-table-column prop="status" label="状态"><template #default="{row}"><el-tag type="success">{{row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></section><el-dialog v-model="visible" :title="editing?'编辑岗位':'新增岗位'" width="440"><el-form label-position="top"><el-form-item label="岗位名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="岗位编码"><el-input v-model="form.code" /></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>
import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{Plus}from'@element-plus/icons-vue';import PageHeader from'../components/PageHeader.vue';import{positionApi}from'../api';const rows=ref([]),loading=ref(false),visible=ref(false),saving=ref(false),editing=ref(null),form=reactive({name:'',code:''});async function load(){loading.value=true;try{rows.value=(await positionApi.list()).data||[]}catch(e){ElMessage.error(e.businessMessage)}finally{loading.value=false}}function open(row=null){editing.value=row;Object.assign(form,row?{name:row.name,code:row.code}:{name:'',code:''});visible.value=true}async function save(){if(!form.name||!form.code)return ElMessage.warning('请完整填写');saving.value=true;try{editing.value?await positionApi.update(editing.value.id,form):await positionApi.create(form);visible.value=false;ElMessage.success('保存成功');await load()}catch(e){ElMessage.error(e.businessMessage)}finally{saving.value=false}}async function remove(row){try{await ElMessageBox.confirm(`确认删除“${row.name}”？`,'删除岗位',{type:'warning'});await positionApi.remove(row.id);ElMessage.success('删除成功');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(e.businessMessage)}}onMounted(load)
</script>
